import{_ as p,a0 as l,w as r,s as d,I as i,x as e,a1 as n,A as a,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"将 VoIP 电话直接连接到 Asterisk 服务器 | LCTT x X-CMD","titleTemplate":false,"description":"将 VoIP 电话直接连接到 Asterisk 服务器 | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"将 VoIP 电话直接连接到 Asterisk 服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"将 VoIP 电话直接连接到 Asterisk 服务器 | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20190228 Connecting a VoIP phone directly to an Asterisk server","title":"将 VoIP 电话直接连接到 Asterisk 服务器","tag":"201903","desc":""},"relativePath":"201903/20190228 Connecting a VoIP phone directly to an Asterisk server.md","filePath":"[post].md"}'),k={name:"201903/20190228 Connecting a VoIP phone directly to an Asterisk server.md"};function g(u,s,h,f,b,c){const t=l("Link");return r(),d("div",null,[s[21]||(s[21]=i("h1",{id:"将-voip-电话直接连接到-asterisk-服务器",tabindex:"-1"},[e("将 VoIP 电话直接连接到 Asterisk 服务器 "),i("a",{class:"header-anchor",href:"#将-voip-电话直接连接到-asterisk-服务器","aria-label":"Permalink to “将 VoIP 电话直接连接到 Asterisk 服务器”"},"​")],-1)),i("p",null,[s[1]||(s[1]=e("在我的 ",-1)),n(t,{href:"https://www.asterisk.org/"},{default:a(()=>[...s[0]||(s[0]=[e("Asterisk",-1)])]),_:1}),s[2]||(s[2]=e(" 服务器上正好有张以太网卡。由于我只用了其中一个，因此我决定将我的 VoIP 电话从本地网络交换机换成连接到 Asterisk 服务器。",-1))]),s[22]||(s[22]=o(`<p>主要的好处是这台运行着未知质量的专有软件的电话，在我的一般家庭网络中不能用了。最重要的是，它不再能访问互联网，因此无需手动配置防火墙。</p><p>以下是我配置的方式。</p><h3 id="私有网络配置" tabindex="-1">私有网络配置 <a class="header-anchor" href="#私有网络配置" aria-label="Permalink to “私有网络配置”">​</a></h3><p>在服务器上，我在 <code>/etc/network/interfaces</code> 中给第二块网卡分配了一个静态 IP：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>auto eth1</span></span>
<span class="line"><span>iface eth1 inet static</span></span>
<span class="line"><span>    address 192.168.2.2</span></span>
<span class="line"><span>    netmask 255.255.255.0</span></span></code></pre></div><p>在 VoIP 电话上，我将静态 IP 设置成 <code>192.168.2.3</code>，DNS 服务器设置成 <code>192.168.2.2</code>。我接着将 SIP 注册 IP 地址设置成 <code>192.168.2.2</code>。</p>`,6)),i("p",null,[s[4]||(s[4]=e("DNS 服务器实际上是一个在 Asterisk 服务器上运行的 ",-1)),n(t,{href:"https://feeding.cloud.geek.nz/posts/setting-up-your-own-dnssec-aware/"},{default:a(()=>[...s[3]||(s[3]=[e("unbound 守护进程",-1)])]),_:1}),s[5]||(s[5]=e("。我唯一需要更改的配置是监听第二张网卡，并允许 VoIP 电话进入：",-1))]),s[23]||(s[23]=o(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>server:</span></span>
<span class="line"><span>    interface: 127.0.0.1</span></span>
<span class="line"><span>    interface: 192.168.2.2</span></span>
<span class="line"><span>    access-control: 0.0.0.0/0 refuse</span></span>
<span class="line"><span>    access-control: 127.0.0.1/32 allow</span></span>
<span class="line"><span>    access-control: 192.168.2.3/32 allow</span></span></code></pre></div><p>最后，我在 <code>/etc/network/iptables.up.rules</code> 中打开了服务器防火墙上的正确端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-A INPUT -s 192.168.2.3/32 -p udp --dport 5060 -j ACCEPT</span></span>
<span class="line"><span>-A INPUT -s 192.168.2.3/32 -p udp --dport 10000:20000 -j ACCEPT</span></span></code></pre></div><h3 id="访问管理页面" tabindex="-1">访问管理页面 <a class="header-anchor" href="#访问管理页面" aria-label="Permalink to “访问管理页面”">​</a></h3><p>现在 VoIP 电话不能在本地网络上用了，因此无法访问其管理页面。从安全的角度来看，这是一件好事，但它有点不方便。</p><p>因此，在通过 ssh 连接到 Asterisk 服务器之后，我将以下内容放在我的 <code>~/.ssh/config</code> 中以便通过 <code>http://localhost:8081</code> 访问管理页面：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Host asterisk</span></span>
<span class="line"><span>    LocalForward 8081 192.168.2.3:80</span></span></code></pre></div><hr>`,8)),i("p",null,[s[7]||(s[7]=e("via: ",-1)),n(t,{href:"https://feeding.cloud.geek.nz/posts/connecting-voip-phone-directly-to-asterisk-server/"},{default:a(()=>[...s[6]||(s[6]=[e("https://feeding.cloud.geek.nz/posts/connecting-voip-phone-directly-to-asterisk-server/",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=e("作者：",-1)),n(t,{href:"https://fmarier.org/"},{default:a(()=>[...s[8]||(s[8]=[e("François Marier",-1)])]),_:1}),s[13]||(s[13]=e(" 选题：",-1)),n(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[9]||(s[9]=[e("lujun9972",-1)])]),_:1}),s[14]||(s[14]=e(" 译者：",-1)),n(t,{href:"https://github.com/geekpi"},{default:a(()=>[...s[10]||(s[10]=[e("geekpi",-1)])]),_:1}),s[15]||(s[15]=e(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:a(()=>[...s[11]||(s[11]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[18]||(s[18]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[16]||(s[16]=[e("LCTT",-1)])]),_:1}),s[19]||(s[19]=e(" 原创编译，",-1)),n(t,{href:"https://linux.cn/"},{default:a(()=>[...s[17]||(s[17]=[e("Linux中国",-1)])]),_:1}),s[20]||(s[20]=e(" 荣誉推出",-1))])])}const m=p(k,[["render",g]]);export{T as __pageData,m as default};
